proc Start {} { 
   if {$::time eq {00:00.00}} { 
       set ::time0 [clock clicks -milliseconds] 
   } 
   every 20 { 
       set m [expr {[clock clicks -milliseconds] - $::time0}] 
       set ::time [format %2.2d:%2.2d.%2.2d \ 
           [expr {$m/60000}] [expr {($m/1000)%60}] [expr {$m%1000/10}]] 
       incr ::titleskip 
       if {$::titleskip >= 12} { 
           wm title . "Timer $::time" 
           set ::titleskip 0 
       } 
   } 
   .start config -state disabled 
   set ::state 1 
} 
